% Function to compute Short Period natural frequency and damping ratio
% The Short Period mode is the "fast" longitudinal mode compared to the "slow" Phugoid mode.
% We identify it by selecting the eigenvalues with the largest magnitude.
function [omega, zeta] = compute_short_period_params(A)
    e = eig(A);

    % Calculate natural frequencies (magnitudes of eigenvalues)
    magnitudes = abs(e);

    % Sort eigenvalues by magnitude in descending order
    [~, sortIdx] = sort(magnitudes, 'descend');

    % The Short Period mode corresponds to the highest frequency eigenvalues.
    % Since complex conjugate pairs have identical magnitude, the top two indices
    % correspond to the Short Period mode. We take the first one for calculation.
    sp_pole = e(sortIdx(1));

    % Natural frequency (rad/s)
    omega = abs(sp_pole);

    % Damping ratio: zeta = -real(pole) / |pole|
    zeta = -real(sp_pole) / omega;
end

% Compute parameters for each flight condition
[omega_sp_1, zeta_sp_1] = compute_short_period_params(A1);
[omega_sp_2, zeta_sp_2] = compute_short_period_params(A2);
[omega_sp_3, zeta_sp_3] = compute_short_period_params(A3);

% Populate the result structure
result.omega_sp_1 = omega_sp_1;
result.zeta_sp_1 = zeta_sp_1;
result.omega_sp_2 = omega_sp_2;
result.zeta_sp_2 = zeta_sp_2;
result.omega_sp_3 = omega_sp_3;
result.zeta_sp_3 = zeta_sp_3;

% Write the results to result.json
jsonStr = jsonencode(result);
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonStr);
fclose(fid);"
